  group(input){this.authorize('group',input.venueId);return this.commit(s=>{if(typeof input.activity!=='string'||!input.activity.trim()||input.activity.length>40||!Number.isInteger(input.people)||input.people<2||input.people>200||!D.findVenue(input.venueId)||!this.dates(input.venueId).includes(input.date)||input.start<6||input.end>23||input.start>=input.end||!/^体验用户\d{2}$/.test(input.contact)||!/^DEMO-\d{8}$/.test(input.phone)||String(input.note||'').length>200)throw new Error('团体申请参数无效');const x={activity:input.activity,date:input.date,start:input.start,end:input.end,people:input.people,contact:input.contact,phone:input.phone,venueId:input.venueId,id:'GROUP-'+(++s.platform.seq),type:'group',user:this.actor,venue:input.venueId,status:'pending',pricingIdentity:P.identity(s.innovation.users[this.actor],this.securityClock()),note:String(input.note||'').slice(0,200)};s.platform.records.push(x);s.groups.push(x);return copy(x);});}
  refund(id){this.authorize('refund');const o=this.getOrder(id);if(!this.refundable(id)&&!this.state.platform.records.some(x=>x.type==='disruption'&&x.orderId===id))throw new Error('当前订单不符合普通退款，查看公开补位或申诉');this.guardTransfer(id);return this.commit(s=>{let x=s.platform.records.find(x=>x.type==='refund'&&x.orderId===id&&x.status!=='rejected');if(!x){x={id:'REF-'+(++s.platform.seq),type:'refund',user:this.actor,venue:o.slots[0].venueId,orderId:id,amount:o.total,status:'pending'};s.platform.records.push(x);}return copy(x);});}
