  ownRequests(){return copy(this.state.platform.records.filter(x=>x.user===this.actor));}
  inventory(slot,ignore){return super.inventory(slot,ignore);}
  waitSlot(slot){this.authorize('waitSlot',D.findProduct(slot.productId)?.venue);const x=this.slot(slot.productId,slot.date,slot.resourceId,slot.start,slot.end);if(D.stamp(x.date,x.start)<=this.now())throw new Error('已过预约时间，不能加入候补');const old=this.state.innovation.queue.find(q=>q.user===this.actor&&q.kind==='slot'&&q.resourceId===x.resourceId&&q.date===x.date&&q.start===x.start&&['waiting','stock_offered'].includes(q.status));if(old)return copy(old);const q=this.commit(s=>{const i=s.innovation,row={id:'WAIT-'+(++i.sequence),sequence:i.sequence,user:this.actor,kind:'slot',productId:x.productId,resourceId:x.resourceId,date:x.date,start:x.start,end:x.end,status:'waiting',createdAt:this.now()};i.queue.push(row);return copy(row);});this.dispatchStock();return q;}
  dispatchStock(){if(!this.state.platform||this.dispatchingStock)return;this.dispatchingStock=true;try{const now=this.now();const expired=this.state.innovation.queue.filter(q=>q.kind==='slot'&&q.status==='stock_offered'&&q.offer.expires<=now);if(expired.length)this.commit(s=>{for(const q of s.innovation.queue)if(expired.some(x=>x.id===q.id))q.status='timed_out';});for(const q of this.state.innovation.queue.filter(q=>q.kind==='slot'&&q.status==='waiting').sort((a,b)=>a.sequence-b.sequence)){const p=D.findProduct(q.productId),x={productId:p.id,venueId:p.venue,venueName:D.findVenue(p.venue).name,productName:p.name,resourceId:q.resourceId,resourceName:p.resources.find(r=>r.id===q.resourceId).name,date:q.date,start:q.start,end:q.end,capacity:p.capacity||1};x.pricing=P.rate(p,x,this.state.innovation.users[q.user],this.state.settings,this.securityClock(),this.context.demo===false);x.cents=x.pricing.actualCents;if(D.stamp(x.date,x.start)<=now||this.inventory(x).remaining<1)continue;try{this.checkQuota([x],q.user);}catch(_){continue;}this.commit(s=>{const row=s.innovation.queue.find(v=>v.id===q.id);row.status='stock_offered';row.offer={slots:[x],expires:now+s.innovation.policy.offerMinutes*60000};});}}finally{this.dispatchingStock=false;}}
  inventory(slot,ignore){if(this.state.platform?.stops.some(x=>x.active&&x.venue===slot.venueId&&(!x.resourceId||x.resourceId===slot.resourceId)&&(!x.date||x.date===slot.date)))return {remaining:0,reason:'场地停用，等待恢复'};let base=super.inventory(slot,ignore);if(D.stamp(slot.date,slot.start)<=this.now())return base;const control=this.state.platform?.controls?.find(x=>D.key(x)===D.key(slot));if(control){if(control.capacity===0)return {remaining:0,reason:'管理员暂停该时段'};let used=0;for(const o of this.state.orders)if(o.id!==ignore&&['pending','paid','using','completed'].includes(o.status)&&(o.status!=='pending'||o.expiresAt>this.now()))for(const x of o.slots)if(D.overlaps(x,slot))used++;if(slot.date===this.dates(slot.venueId)[0]&&slot.resourceId===D.findProduct(slot.productId).resources[0].id&&slot.start===12)used++;base={remaining:Math.max(0,control.capacity-used),reason:'管理员库存配置'};}const held=this.state.innovation?.queue.filter(q=>q.id!==this.waitAcceptId&&q.kind==='slot'&&q.status==='stock_offered'&&q.offer.expires>this.now()&&q.offer.slots.some(x=>D.overlaps(x,slot))).length||0;return {remaining:Math.max(0,base.remaining-held),reason:held?'候补确认保留':base.reason};}
