  acceptWait(id,quote,method='北理工支付',fail=false){this.authorize('acceptWait');this.dispatchStock();const q=this.state.innovation.queue.find(x=>x.id===id&&x.user===this.actor);if(q?.status==='accepted'&&q.newOrderId)return this.getOrder(q.newOrderId);if(!q||q.status!=='stock_offered'||q.offer.expires<=this.now())throw new Error('候补确认已失效');const slots=q.offer.slots.map(x=>this.slot(x.productId,x.date,x.resourceId,x.start,x.end)),total=slots.reduce((n,x)=>n+x.cents,0);if(quote!==JSON.stringify(slots.map(x=>x.pricing)))throw new Error('身份或价格已变，请重新报价并确认');if(fail||!['北理工支付','余额支付'].includes(method))throw new Error('候补模拟支付失败，确认保留期内可重试');if(method==='余额支付'&&this.state.balance<total)throw new Error('演示余额不足');this.checkQuota(slots);this.waitAcceptId=id;try{if(slots.some(x=>this.inventory(x).remaining<1))throw new Error('库存已变');return this.commit(s=>{const row=s.innovation.queue.find(x=>x.id===id),now=this.now(),o={id:'DEMO-'+String(++s.serial).padStart(6,'0'),token:'stock:'+id,ownerId:this.actor,credentialVersion:1,slots,total,status:'paid',payment:method,createdAt:now,expiresAt:now,paidAt:now,events:[{at:now,action:'按候补顺序确认并付款'}]};if(method==='余额支付'){s.balance-=total;s.ledger.unshift({id:id+'-pay',cents:-total,reason:'候补模拟付款',orderId:o.id,at:now});}s.orders.unshift(o);row.status='accepted';row.newOrderId=o.id;s.innovation.admissions.push({user:this.actor,at:now,slots:slots.length,orderId:o.id});return copy(o);});}finally{this.waitAcceptId='';}}
